# Centro de Isla Ceniza (C7, contract 53): a copy of centro_ambar.map (nurse, PC, respawn point). column = i, row = j.
@map centro_ceniza
@size 10 8
@interior yes
@bg 3
@fill floor_lab
@var club_sel 4
@var club_res 5
@var club_res2 7
@spawn door 4 6 N
@legend
  .  tile=floor_lab
  a  tile=none object=wall_j
  b  tile=none object=wall_i
  c  tile=floor_lab object=counter
  d  tile=none object=wall_win_j
  e  tile=mat
  f  tile=none object=wall_corner
  g  tile=floor_lab object=bookshelf interact=look text=centro.books
  h  tile=floor_lab object=healer
  i  tile=floor_lab face=SW id=nurse npc=nurse script=nurse
  j  tile=floor_lab object=pc interact=look script=pc_box
  X  tile=floor_lab npc=cientifico_s id=club face=SW script=club
@grid
  fadaaadaaa
  b.g.hi..Xj
  b..cccc...
  b.........
  b.........
  b.........
  b.........
  b...ee....
@warp e -> isla_ceniza spawn=centro_door
@script nurse npc
    ask gl.center.ask
    jv 0 1 yes
    say gl.center.bye
    end
  yes:
    fade_out
    wait 1500
    bond heal 0       # contract 65: +1 friendship for every creature that needs the healing (before it is healed)
    heal_party
    respawn door
    fade_in
    say gl.center.done
@end
# The PC terminal (M5-C, contract 25.3): the box screen of the PC plugin.
@script pc_box interact
    pc
@end
# The Club de Enlace attendant (contract 61; Club de Enlace receptionist): the IR link's front door. Warns it is experimental, then a four-row menu: trade / battle (the exhibition,
# trainer `amigo`) / the IR self-test / leave. After a cancelled or failed attempt the menu comes back (the link scene already told what happened).
@script club npc
    npc_face_hero club
    say gl.club.hello
  menu:
    elevator club_sel gl.club.trade gl.club.battle gl.club.test gl.club.exit
    jv club_sel 0 trade
    jv club_sel 1 battle
    jv club_sel 2 test
    end
  trade:
    link trade club_res
    jv club_res 0 fail
    jv club_res 1 out
    jmp menu
  battle:
    link battle club_res amigo
    jv club_res 0 fail
    jv club_res 1 fight
    jmp menu
  fight:
    battle amigo club_res2
    say gl.club.thanks
  out:
    end
  test:
    link selftest club_res
    jv club_res 0 fail
    jmp menu
  fail:
    say gl.club.fail
@end
